"""Fetch official e-Laws API and fail closed if a quoted excerpt disappears."""
import json, re, html, urllib.request
from pathlib import Path
DATE = '2026-11-24'
ROOT = Path(__file__).resolve().parents[1]
def write(name, obj):
    (ROOT/name).write_text(json.dumps(obj, indent=2, ensure_ascii=False)+'\n', encoding='utf8')
texts={}
for ident, kind in [('06r17','statute'),('060516','regulation')]:
    url=f'https://www.ontario.ca/laws/api/v2/legislation/en/doc-search/{kind}/{ident}'
    cache=ROOT/f'scripts/.cache/{ident}.json'
    if not cache.exists():
        cache.parent.mkdir(exist_ok=True)
        cache.write_bytes(urllib.request.urlopen(url).read())
    texts[ident]=re.sub(r'\s+',' ',html.unescape(re.sub('<[^>]+>',' ',json.loads(cache.read_text(encoding='utf8'))['content'])))
rules=[]; audit=['# RTA verification',f'Retrieved {DATE}. Official e-Laws document API; excerpts normalize whitespace only. Not legal advice.','Rules are conditional on RTA applicability. No section is inferred from secondary commentary.']
def add(id,section,title,patterns,status,lesson,quote,ident='06r17',fuzzy=[]):
    text=texts[ident]
    assert quote in text, f'UNVERIFIED: {id}'
    kind='statute' if ident=='06r17' else 'regulation'
    url=f'https://www.ontario.ca/laws/{kind}/{ident}'
    rules.append(dict(id=id,section=section,title=title,patterns=patterns,fuzzy_patterns=fuzzy,status=status,lesson_plain=lesson,lesson_simple_english=lesson,source_url=url))
    audit.extend([f'\n## {id} — {section}',f'Source: {url} (retrieved {DATE})',f'API: https://www.ontario.ca/laws/api/v2/legislation/en/doc-search/{kind}/{ident}',f'> {quote}',f'Interpretation: {lesson}'])
add('damage_deposit','s.105(1)','Damage/security deposit',[r'\b(?:damage|security|cleaning|pet)\s+deposit\b',r'first\s*\+\s*last\s*\+\s*(?:damage\s+)?deposit'],'void','A landlord cannot require a damage/security deposit. A lawful rent deposit and the regulated refundable key deposit are different.', '105 (1) The only security deposit that a landlord may collect is a rent deposit collected in accordance with section 106.',fuzzy=[r'additional\s+deposit'])
add('excess_rent_deposit','s.106(2)','Excess rent deposit',[r'(?:two|three|[2-9])\s*months?[’\x27]?\s*(?:rent\s*)?(?:deposit|up\s*front)',r'(?:rent\s*)?deposit\s*(?:of\s*)?(?:two|three|[2-9])\s*months?'],'void','A required rent deposit is capped at the lesser of one rent period and one month. Compare any stated dollar deposit to the actual rent.', '(2) The amount of a rent deposit shall not be more than the lesser of the amount of rent for one rent period and the amount of rent for one month.')
add('no_pets','s.14','No-pets provision',[r'\bno[ -]pets?(?:\s+allowed)?\b',r'\bpets?\s+(?:are\s+)?(?:not\s+(?:allowed|permitted)|prohibited)\b'],'void','A tenancy agreement cannot ban animals. Other animal-related laws and grounds for an LTB application may still matter.', '14 A provision in a tenancy agreement prohibiting the presence of animals in or about the residential complex is void.')
add('postdated_cheques','s.108','Required automatic payment/post-dated cheques',[r'\b(?:\d+\s+)?post[ -]?dated\s+che(?:que|ck)s?\b',r'(?:mandatory|required|must\s+(?:use|provide))\s+(?:automatic\s+(?:debit|payment)|auto[ -]?debit)'],'void','A landlord cannot require post-dated cheques or automatic payments. A voluntary arrangement is different.', '108 Neither a landlord nor a tenancy agreement shall require a tenant or prospective tenant to, (a) provide post-dated cheques or other negotiable instruments for payment of rent; or (b) permit automatic debiting of the tenant’s or prospective tenant’s account at a financial institution, automatic charging of a credit card or any other form of automatic payment for the payment of rent.')
add('entry_notice','s.27(1); s.26','Unrestricted entry',[r'landlord\s+(?:can|may|will)\s+enter\s+(?:any\s*time|anytime|without\s+(?:notice|24))',r'(?:entry|enter)\s+without\s+(?:prior\s+)?notice'],'void','Ordinary entry under s.27 requires at least 24 hours written notice and a permitted reason. Section 26 permits exceptions, including emergencies and consent at entry.', '27 (1) A landlord may enter a rental unit in accordance with written notice given to the tenant at least 24 hours before the time of entry under the following circumstances:')
add('maintenance_waiver','s.20(1); s.4(1)','Maintenance duty waiver',[r'tenant\s+(?:does|pays\s+for|responsible\s+for)\s+all\s+repairs',r'landlord\s+(?:is\s+)?not\s+responsible\s+for\s+(?:any\s+)?repairs'],'void','A landlord remains responsible for repair, habitation and required standards. An agreement cannot waive the Act.', '20 (1) A landlord is responsible for providing and maintaining a residential complex, including the rental units in it, in a good state of repair and fit for habitation and for complying with health, safety, housing and maintenance standards.',fuzzy=[r'\bas[ -]is\b'])
add('lockout','s.24; s.39','Self-help eviction/lockout',[r'(?:change|changing)\s+(?:the\s+)?locks\s+(?:if|when|without)',r'evict\s+(?:you\s+)?without\s+(?:the\s+)?(?:LTB|board|court)',r'immediate\s+(?:eviction|lock[ -]?out)'],'void','A landlord cannot recover possession of an occupied unit without a Board order, except abandonment/vacating; changing locks requires replacement keys.', '39 A landlord shall not recover possession of a rental unit subject to a tenancy unless, (a) the tenant has vacated or abandoned the unit; or (b) an order of the Board evicting the tenant has authorized the possession.')
add('deposit_interest','s.106(6); s.106(10)','Rent-deposit interest/use',[r'non[ -]?refundable\s+(?:last\s*month|rent\s*deposit)',r'no\s+interest\s+(?:on|for)\s+(?:the\s+)?(?:rent\s+)?deposit'],'questionable','Rent-deposit interest is due annually at the guideline rate. A rent deposit is for the last rent period, not a general non-refundable fee.', '(6) A landlord of a rental unit shall pay interest to the tenant annually on the amount of the rent deposit at a rate equal to the guideline determined under section 120 that is in effect at the time payment becomes due.')
add('standard_lease','s.12.1(1)','Standard lease information',[r'\bstandard\s+lease\b'],'info','Prescribed classes of tenancies require the prescribed agreement form. This lesson does not assume every sublet is a prescribed tenancy.', '12.1 (1) Every tenancy agreement that is entered into in respect of a tenancy of a prescribed class on or after the date prescribed for that class of tenancies shall comply with the following requirements: 1. The tenancy agreement shall be in the form prescribed for that class of tenancies.')
add('sublet_consent','s.97(1)-(2)','Sublet consent',[r'\b(?:sublet|subletting|sublease)\b'],'info','Subletting requires landlord consent; a landlord shall not arbitrarily or unreasonably withhold consent to a potential subtenant.', '(2) A landlord shall not arbitrarily or unreasonably withhold consent to the sublet of a rental unit to a potential subtenant.')
add('owner_shared','s.5(i)','Owner-shared kitchen/bath exemption',[r'shar(?:e|ed|ing)\s+(?:a\s+|the\s+)?(?:kitchen|bathroom|bath)\s+with\s+(?:the\s+)?(?:owner|landlord)'],'info','The Act may not apply where sharing a kitchen or bathroom with the resident owner or specified family is required. Confirm who lives in the building.', '(i) living accommodation whose occupant or occupants are required to share a bathroom or kitchen facility with the owner, the owner’s spouse, child or parent or the spouse’s child or parent, and where the owner, spouse, child or parent lives in the building in which the living accommodation is located;')
add('key_deposit','O. Reg. 516/06 s.17(3)','Refundable key deposit',[r'refundable\s+key\s+deposit'],'info','A refundable key/device/card deposit may not exceed expected direct replacement cost. The amount and refundability need checking.', '3. Payment of a refundable key, remote entry device or card deposit, not greater than the expected direct replacement costs.','060516')
# Audit supporting sections for multi-section lessons.
for section,quote in [('s.4(1)','4 (1) Subject to subsection 12.1 (11) and section 194, a provision in a tenancy agreement that is inconsistent with this Act or the regulations is void.'),('s.24','24 A landlord shall not alter the locking system on a door giving entry to a rental unit or residential complex or cause the locking system to be altered during the tenant’s occupancy of the rental unit without giving the tenant replacement keys.'),('s.37(1)','37 (1) A tenancy may be terminated only in accordance with this Act.'),('s.26(1)','26 (1) A landlord may enter a rental unit at any time without written notice, (a) in cases of emergency; or (b) if the tenant consents to the entry at the time of entry.'),('s.106(10)','(10) A landlord shall apply a rent deposit that a tenant has paid to the landlord or to a former landlord in payment of the rent for the last rent period before the tenancy terminates.'),('s.97(1)','97 (1) A tenant may sublet a rental unit to another person with the consent of the landlord.')]:
    assert quote in texts['06r17'],section
    audit.extend([f'\n## Supporting {section}',f'Source: https://www.ontario.ca/laws/statute/06r17; retrieved {DATE}',f'> {quote}'])
write('data/rta_rules.json',dict(version='1.0.0',retrieved=DATE,rules=rules))
(ROOT/'data/RTA-VERIFICATION.md').write_text('\n\n'.join(audit)+'\n',encoding='utf8')
print(f'Verified {len(rules)} rules against official document text')

